node - <<'NODE'
const assert = require('node:assert/strict');
const {runTarget, runAdjacent} = require('./src/temporal-flow.js');
(async () => {
  for (const clickBeforeReady of [true, false]) {
    assert.deepEqual(await runTarget({clickBeforeReady, loadedFlag: true}), {value:'premium-action', events:['premium-action']});
    assert.deepEqual(await runTarget({clickBeforeReady, loadedFlag: false}), {value:'none', events:['none']});
  }
  assert.deepEqual(await runAdjacent({clickBeforeReady:true}), {value:'emergency-action', events:['emergency-action']});
  assert.deepEqual(await runAdjacent({clickBeforeReady:false}), {value:'none', events:['none']});
  console.log('premium and emergency checks passed');
})().catch(error => { console.error(error); process.exitCode = 1; });
